import { resolveActiveCharacter } from '@shared/config';

// Illustrations generated by scripts/gen-icons.mjs live in assets/ui/ (vite publicDir) → served at /ui/ in dev and
// dist/renderer/ui/ in the packaged app; resolve them relative to the page like rtc.ts does for vendor scripts.
export function uiAsset(file: string): string {
  return new URL(`../ui/${file}`, location.href).toString();
}

/** Quick-task chip icons keyed by DEFAULT_CONFIG.quickTasks ids (assets/ui/task-<id>.png, 128 px, shown at 16 px). */
export const TASK_ICONS: Record<string, string> = Object.fromEntries(
  ['notes-todo', 'tidy-screenshots', 'weather-notify', 'web-headlines', 'clipboard-md', 'screen-describe', 'csv-report', 'sysinfo-notify']
    .map(id => [id, uiAsset(`task-${id}.png`)]),
);

/** Task 09: the active character's Q 版 pictures as URLs, falling back to the bundled 小栖 illustrations when the
 *  character has none. `own` tells whether the picture is character-specific (the status-bar avatar only shows then). */
export function characterArt(config: import('@shared/config').PublicConfig): { hero: string; bust: string; connecting: string; own: boolean; ownBust: boolean } {
  const a = resolveActiveCharacter(config);
  const own = Boolean(a.artHeroPath), ownBust = Boolean(a.artBustPath);
  const url = (p: string) => window.companion.assetUrl(p);
  return {
    hero: own ? url(a.artHeroPath!) : uiAsset('hero-empty.png'),
    bust: ownBust ? url(a.artBustPath!) : uiAsset('bust-xiaoqi.png'),
    // 小栖 has a dedicated dozing picture for「数字人正在创建中」; other characters show their waving hero there.
    connecting: own ? url(a.artHeroPath!) : uiAsset('hero-connecting.png'),
    own, ownBust,
  };
}
